 mck:[MK,MCKAY],mck1:[MK+', lines 1-4',sl(MCKAY,1,4)],mck3:[MK+', lines 9-12',sl(MCKAY,9,12)],
 ros:[RO,ROSS],ros8:[RO+', lines 1-8',sl(ROSS,1,8)],ros6:[RO+', lines 9-14',sl(ROSS,9,14)],
